// Cloudflare entry point. Wraps the OpenNext worker so that addresses which aren't real pages return a 404 status
// (Next renders the "not found" page, but with cacheComponents it can arrive with a 200, which Google calls a soft 404).
// Real pages are the ones in the sitemap. If the sitemap can't be read, nothing is blocked.

// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- the file only exists after a Cloudflare build
// @ts-ignore: generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";
// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- the file only exists after a Cloudflare build
// @ts-ignore: generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";

type Fetcher = { fetch: (req: Request, env: unknown, ctx: unknown) => Promise<Response> };
const app = handler as Fetcher;

let known: Promise<Set<string> | null> | null = null;

function knownPaths(origin: string, env: unknown, ctx: unknown) {
  known ??= app
    .fetch(new Request(`${origin}/sitemap.xml`), env, ctx)
    .then((r) => (r.ok ? r.text() : null))
    .then((xml) => (xml ? new Set([...xml.matchAll(/<loc>https?:\/\/[^/<]+([^<]*)<\/loc>/g)].map((m) => clean(m[1])).concat("/")) : null))
    .catch(() => null)
    .then((set) => {
      if (!set || set.size < 10) known = null; // try again on a later request
      return set && set.size >= 10 ? set : null;
    });
  return known;
}

const clean = (p: string) => p.replace(/\/+$/, "") || "/";

/** Only page addresses are checked. Files, Next internals and API routes pass straight through. */
const isPage = (p: string) => !p.includes(".") && !/^\/(_next|api|cdn-cgi|_vercel)(\/|$)/.test(p);

/** The *.workers.dev test address must never compete with the real domain in search. */
async function noindexOnTestHost(url: URL, res: Promise<Response>) {
  const r = await res;
  if (!url.hostname.endsWith(".workers.dev")) return r;
  const headers = new Headers(r.headers);
  headers.set("x-robots-tag", "noindex");
  return new Response(r.body, { status: r.status, statusText: r.statusText, headers });
}

const CANONICAL_HOST = "ditchsubs.app";

const worker = {
  async fetch(req: Request, env: unknown, ctx: unknown) {
    const url = new URL(req.url);
    // One address only: http and www forward permanently to https://ditchsubs.app.
    if ((url.hostname === `www.${CANONICAL_HOST}` || (url.hostname === CANONICAL_HOST && url.protocol === "http:"))) {
      return Response.redirect(`https://${CANONICAL_HOST}${url.pathname}${url.search}`, 301);
    }
    return noindexOnTestHost(url, route(req, url, env, ctx));
  },
};

async function route(req: Request, url: URL, env: unknown, ctx: unknown): Promise<Response> {
  const path = clean(url.pathname);
  if ((req.method === "GET" || req.method === "HEAD") && isPage(path)) {
    const set = await knownPaths(url.origin, env, ctx);
    if (set && !set.has(path)) {
      const res = await app.fetch(req, env, ctx);
      const headers = new Headers(res.headers);
      headers.set("cache-control", "public, max-age=0, must-revalidate");
      headers.set("x-robots-tag", "noindex");
      return new Response(res.body, { status: 404, headers });
    }
  }
  return app.fetch(req, env, ctx);
}

export default worker;
